/* Reports are generated by the backend; only its validated, isolated document is rendered here. */
class HealthReports {
  constructor({ onChange, onNavigate, onDiscuss, helpers }) {
    Object.assign(this, { onChange, onNavigate, onDiscuss, ...helpers });
    this.kind = "daily";
    this.date = this.today();
    this.items = [];
    this.schedules = [];
    this.status = "idle";
    this.detail = null;
    this.bundle = null;
    this.cursor = null;
    this.filter = false;
    this.settingsOpen = false;
    this.message = "";
    this.loadingDetail = false;
    this.active = false;
    this.sequence = 0;
    document.addEventListener("click", (e) => {
      const el = e.target.closest("[data-rp]");
      if (el) {
        e.preventDefault();
        void this.action(el.dataset.rp, el);
      }
    });
    document.addEventListener("change", (e) => {
      if (e.target.matches("[data-report-date]")) this.date = e.target.value;
    });
    document.addEventListener("submit", (e) => {
      if (e.target.matches("[data-report-settings]")) {
        e.preventDefault();
        void this.saveSettings(e.target);
      }
    });
    window.addEventListener("message", (e) => {
      const frame = document.querySelector("[data-health-report-frame]"),
        d = e.data;
      if (
        !frame ||
        e.source !== frame.contentWindow ||
        !this.bundle ||
        !d ||
        d.channel !== this.bundle.channel ||
        d.type !== "health-report-height" ||
        !Number.isFinite(d.height) ||
        d.height < 0 ||
        d.height > 80000
      )
        return;
      frame.style.height = Math.max(180, Math.ceil(d.height)) + "px";
    });
  }
  e(v) {
    return this.escapeHtml(v);
  }
  async api(path, options) {
    const response = await fetch("/api/" + path, {
      cache: "no-store",
      ...options,
    });
    const body = await response.json();
    if (!response.ok) throw Error(body.error || "reports_unavailable");
    return body;
  }
  changed() {
    this.onChange();
  }
  async open() {
    this.active = true;
    const q = new URLSearchParams(location.search);
    if (!q.get("report")) {
      this.detail = null;
      this.bundle = null;
    }
    if (!this.filter) {
      this.kind = "daily";
      this.date = this.today();
    }
    await this.load();
    if (q.get("report")) await this.read(q.get("report"), false);
  }
  leave() {
    this.active = false;
    clearTimeout(this.pollTimer);
    this.sequence++;
  }
  error(code) {
    return (
      {
        report_not_configured: "报告模型尚未配置，配置后可重新生成。",
        insufficient_data:
          "这个周期还没有可分析的记录。可以补充状态记录，或等 Garmin 同步后重试。",
        invalid_report: "这次报告未通过检查，请重新生成。",
        reports_unavailable: "报告暂时无法读取，请稍后重试。",
        report_unavailable: "本次生成未完成，服务会尝试重试。",
        period_not_closed: "请选择已经结束的日期或完整周。",
        queue_full: "当前待生成报告较多，请稍后重试。",
        rate_limited: "操作较频繁，请稍后再试。",
        report_timeout: "生成超时，服务会尝试重试。",
        worker_interrupted: "生成中断，服务会尝试恢复。",
      }[code] || "操作未完成，请稍后重试。"
    );
  }
  async load(append = false, quiet = false) {
    const seq = ++this.sequence;
    if (!quiet) {
      this.status = "loading";
      this.changed();
    }
    try {
      const q = new URLSearchParams({ kind: this.kind });
      if (append && this.cursor) q.set("cursor", this.cursor);
      if (this.filter) {
        const start =
          this.kind === "weekly" ? this.weekStart(this.date) : this.date;
        q.set("from", start);
        q.set("to", start);
      }
      const [data, settings] = await Promise.all([
        this.api("health-reports?" + q),
        this.api("health-report-settings"),
      ]);
      if (seq !== this.sequence) return;
      const previous = JSON.stringify(
        this.items.map((i) => ({ ...i, stage: i.stage?.split(":")[0] })),
      );
      this.items = append ? [...this.items, ...data.reports] : data.reports;
      this.cursor = data.next_cursor;
      this.schedules = settings.schedules;
      this.status = "ready";
      const changed =
        previous !==
        JSON.stringify(
          this.items.map((i) => ({ ...i, stage: i.stage?.split(":")[0] })),
        );
      let trackedChanged = false;
      if (
        this.trackedRun &&
        ["queued", "running", "retrying"].includes(this.trackedRun.state)
      ) {
        const result = await this.api(
          "health-report-runs/" + this.trackedRun.id,
        );
        if (seq !== this.sequence) return;
        trackedChanged =
          result.run.state !== this.trackedRun.state ||
          result.run.stage?.split(":")[0] !==
            this.trackedRun.stage?.split(":")[0];
        this.trackedRun = result.run;
        if (
          this.trackedRun.state === "completed" &&
          this.detail?.id === this.trackedRun.report_id
        )
          await this.read(this.trackedRun.report_id, false);
      }
      if ((!quiet || changed || trackedChanged) && !this.settingsOpen)
        this.changed();
      if (quiet && this.detail) {
        const found = this.items.find((i) => i.id === this.detail.id);
        if (found?.generated_at && found.generated_at !== this.detail.generated_at)
          await this.read(found.id, false);
      }
      this.poll();
    } catch (e) {
      if (seq !== this.sequence) return;
      this.status = "error";
      this.message = this.error(e.message);
      this.changed();
      if (quiet) this.poll(true);
    }
  }
  poll(force = false) {
    clearTimeout(this.pollTimer);
    if (
      this.active &&
      (force ||
        (this.trackedRun &&
          ["queued", "running", "retrying"].includes(this.trackedRun.state)) ||
        this.items.some((i) =>
          ["queued", "running", "retrying"].includes(i.state),
        ))
    )
      this.pollTimer = setTimeout(() => void this.load(false, true), 4000);
  }
  weekStart(date) {
    const day = new Date(date + "T12:00:00Z").getUTCDay();
    return this.shiftDate(date, -((day + 6) % 7));
  }
  range(r) {
    return r.kind === "weekly"
      ? `${r.period_start} — ${this.shiftDate(r.period_end_exclusive, -1)}`
      : r.period_start;
  }
  stamp(
    v,
    timezone = this.detail?.timezone ||
      this.schedules.find((s) => s.kind === this.kind)?.timezone ||
      "Asia/Shanghai",
  ) {
    return v
      ? new Date(v).toLocaleString("zh-CN", {
          timeZone: timezone,
          hour12: false,
        })
      : "—";
  }
  label(r) {
    return (
      {
        queued: "等待生成",
        running:
          {
            collecting: "整理数据",
            analyzing: "正在分析",
            validating: "检查报告",
            reviewing: "核对结论",
            publishing: "保存报告",
          }[r.stage?.split(":")[0]] || "正在生成",
        retrying: "等待自动重试",
        completed: "已生成",
        failed: "生成失败",
        insufficient_data: "资料不足",
      }[r.state] || "尚未生成"
    );
  }
  async read(id, push = true) {
    if (!/^[1-9]\d{0,17}$/.test(id)) return;
    const token = Symbol();
    this.detailToken = token;
    this.loadingDetail = true;
    this.message = "";
    this.changed();
    try {
      const value = await this.api(`health-reports/${id}`);
      if (this.detailToken !== token || !this.active) return;
      this.detail = value.report;
      this.bundle = value.render;
      const changedKind = this.kind !== this.detail.kind;
      this.kind = this.detail.kind;
      if (changedKind) void this.load(false, true);
      const u = new URL(location.href);
      u.searchParams.set("report", id);
      u.searchParams.delete("revision");
      history[push ? "pushState" : "replaceState"]({}, "", u);
    } catch (e) {
      if (this.detailToken === token) this.message = this.error(e.message);
    } finally {
      if (this.detailToken === token) {
        this.loadingDetail = false;
        this.changed();
      }
    }
  }
  clearDetail() {
    this.detailToken = null;
    this.detail = null;
    this.bundle = null;
    this.loadingDetail = false;
    const u = new URL(location.href);
    u.searchParams.delete("report");
    u.searchParams.delete("revision");
    history.pushState({}, "", u);
  }
  async action(name, el) {
    if (name === "kind") {
      this.kind = el.dataset.kind;
      this.date =
        this.kind === "weekly"
          ? this.shiftDate(this.weekStart(this.today()), -7)
          : this.today();
      this.clearDetail();
      this.message = "";
      await this.load();
    }
    if (name === "read") await this.read(el.dataset.id);
    if (name === "back") {
      this.clearDetail();
      this.changed();
      await this.load();
    }
    if (name === "refresh") await this.load();
    if (name === "more") await this.load(true);
    if (
      ["filter", "generate"].includes(name) &&
      (!/^\d{4}-\d{2}-\d{2}$/.test(this.date) ||
        !Number.isFinite(Date.parse(this.date)))
    ) {
      this.message = "请先选择有效的报告日期。";
      this.changed();
      return;
    }
    if (name === "filter") {
      this.filter = !this.filter;
      await this.load();
    }
    if (name === "settings") {
      this.settingsOpen = !this.settingsOpen;
      this.changed();
    }
    if (name === "generate" || name === "regenerate" || name === "retry") {
      if (this.generating) return;
      this.generating = true;
      this.message = "";
      this.changed();
      try {
        const kind =
          name === "regenerate"
            ? this.detail.kind
            : el.dataset.kind || this.kind;
        const start =
          name === "regenerate"
            ? this.detail.period_start
            : el.dataset.date || this.date;
        const requestKey = crypto.randomUUID
          ? crypto.randomUUID()
          : this.uuid();
        const queued = await this.api("health-reports/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            kind,
            period_start: start,
            regenerate: name === "regenerate",
            request_key: requestKey,
          }),
        });
        this.trackedRun = queued.run;
        this.kind = kind;
        this.filter = false;
        await this.load();
        this.message =
          queued.run?.state === "completed"
            ? "这个周期已有报告，可直接阅读或在详情中重新生成。"
            : "已加入生成队列，离开页面后仍会继续。";
      } catch (e) {
        this.message = this.error(e.message);
      } finally {
        this.generating = false;
        this.changed();
      }
    }
    if (name === "discuss" && this.detail)
      this.onDiscuss(
        { report_id: this.detail.id },
        `我想聊聊 ${this.range(this.detail)} 这份${this.detail.kind === "daily" ? "日报" : "周报"}，请结合报告依据和建议帮我理解。`,
      );
  }
  uuid() {
    return "10000000-1000-4000-8000-100000000000".replace(/[018]/g, (c) =>
      (
        Number(c) ^
        (crypto.getRandomValues(new Uint8Array(1))[0] & (15 >> (Number(c) / 4)))
      ).toString(16),
    );
  }
  async saveSettings(form) {
    if (this.saving) return;
    this.saving = true;
    this.message = "";
    const values = new FormData(form);
    const schedules = this.schedules.map((s) => ({
      kind: s.kind,
      enabled: values.has(s.kind + "-enabled"),
      local_time: values.get(s.kind + "-time"),
      timezone: values.get("timezone"),
      weekday: Number(values.get("weekday")),
    }));
    try {
      const result = await this.api("health-report-settings", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ schedules }),
      });
      this.schedules = result.schedules;
      this.message = "自动生成设置已保存。";
      this.settingsOpen = false;
    } catch (e) {
      this.message = this.error(e.message);
    } finally {
      this.saving = false;
      this.changed();
    }
  }
  homeSummary() {
    const summary = this.items.find(
      (r) => this.currentReport(r) && r.summary,
    )?.summary;
    if (summary) return summary;
    const schedule = this.schedules.find((s) => s.kind === "daily");
    if (!schedule) return "定时生成日报与周报，串起记录中的变化。";
    return schedule.enabled
      ? "下次日报：" + this.stamp(schedule.next_run_at, schedule.timezone)
      : "自动日报已关闭，可以手动生成健康回顾。";
  }
  currentReport(r) {
    return ["independent_fact_check_v1", "source_validation_v1"].includes(
      r.review_method,
    );
  }
  archiveTitle(r) {
    if (r.generated_at && !this.currentReport(r))
      return r.kind === "daily" ? "健康日报" : "健康周报";
    return r.title || "正在整理这一段健康记录";
  }
  archiveSummary(r) {
    if (r.generated_at && !this.currentReport(r))
      return "已保存的健康回顾，点开查看详情。";
    return (
      r.summary ||
      (r.state === "insufficient_data"
        ? "这段时间还没有可用于分析的资料。"
        : r.state === "failed"
          ? "这次报告未完成，可以重新尝试。"
          : "报告会根据真实记录选择值得关注的变化。")
    );
  }
  renderSettings() {
    if (!this.settingsOpen) return "";
    return `<form class="rp-settings" data-report-settings><div class="rp-section-head"><h2>自动生成设置</h2><button type="button" class="icon-button" data-rp="settings" aria-label="关闭设置">${this.icon("close")}</button></div><div class="rp-settings-grid">${this.schedules.map((s) => `<label class="rp-schedule"><span><input type="checkbox" name="${s.kind}-enabled" ${s.enabled ? "checked" : ""}> 自动${s.kind === "daily" ? "日报" : "周报"}</span><input type="time" name="${s.kind}-time" value="${this.e(s.local_time)}" required aria-label="${s.kind === "daily" ? "日报" : "周报"}生成时间"><small>下次：${s.enabled ? this.e(this.stamp(s.next_run_at, s.timezone)) : "已关闭"}</small></label>`).join("")}<label>时区<select name="timezone">${[...new Set([this.schedules[0]?.timezone || "Asia/Shanghai", "Asia/Shanghai", "Asia/Tokyo", "Europe/London", "America/New_York", "UTC"])].map((t) => `<option value="${this.e(t)}" ${t === this.schedules[0]?.timezone ? "selected" : ""}>${this.e(t)}</option>`).join("")}</select></label><label>周报生成日<select name="weekday">${["周日", "周一", "周二", "周三", "周四", "周五", "周六"].map((v, i) => `<option value="${i}" ${i === (this.schedules.find((s) => s.kind === "weekly")?.weekday ?? 1) ? "selected" : ""}>${v}</option>`).join("")}</select></label></div><p class="rp-caption">日报回顾前一天，周报回顾上一完整周。设备运行且联网时，后台会按时生成。</p><button class="primary-btn" type="submit" ${this.saving ? "disabled" : ""}>保存设置</button></form>`;
  }
  render() {
    const e = (v) => this.e(v),
      d = this.detail,
      active =
        (d &&
        this.trackedRun?.report_id === d.id &&
        ["queued", "running", "retrying"].includes(this.trackedRun.state)
          ? this.trackedRun
          : null) ||
        this.items.find(
          (i) =>
            i.id === d?.id &&
            ["queued", "running", "retrying"].includes(i.state),
        );
    return `<section class="reports-page"><div class="page-heading rp-heading"><div><div class="rp-eyebrow">HEALTH JOURNAL</div><h1>健康报告</h1><p>把记录串起来，看见身体的变化。</p></div><button class="rp-secondary" type="button" data-rp="settings">${this.icon("calendar")}自动生成设置</button></div>${this.renderSettings()}${this.message ? `<div class="rp-message" role="status">${e(this.message)}</div>` : ""}${
      d
        ? `<div class="rp-detail-tools"><button class="text-link" type="button" data-rp="back">← 返回报告</button></div><div data-share-scope="report"><header class="rp-report-heading">${typeof HealthShare !== "undefined" ? HealthShare.button({ title: d.title, context: this.range(d) }) : ""}<span class="rp-tag">${d.kind === "daily" ? "日报" : "周报"} · ${e(this.range(d))}</span><button class="icon-button context-chat-action" type="button" data-rp="discuss" aria-label="对话讨论这份报告" title="对话讨论这份报告">${this.icon("chat")}</button><h2>${e(d.title)}</h2><p>${e(d.summary)}</p><div class="rp-caption">AI 生成 · ${e(this.stamp(d.generated_at))} · ${e(d.timezone)} · 请结合原始记录判断</div></header><div class="rp-coverage"><strong>数据覆盖</strong>${(
            d.coverage || []
          )
            .filter(
              (s) =>
                !["profile", "conversations", "recipes"].includes(s.source),
            )
            .map(
              (s) =>
                `<span class="rp-source ${["available", "no_records"].includes(s.status) ? "" : "incomplete"}">${e({ garmin: "身体指标", activities: "实际运动", plans: "训练安排", status: "状态记录", meals: "饮食记录" }[s.source] || s.source)} · ${e({ available: "已读取", no_records: "无记录", not_integrated: "尚未接入", unavailable: "读取失败", partial: "部分数据" }[s.status] || s.status)}</span>`,
            )
            .join(
              "",
            )}<details><summary>查看数据时间</summary><p>报告期：${e(this.range(d))}；读取截至 ${e(this.stamp(d.data_context?.as_of))}。历史计划按生成时可读取的日历回看，不代表当时计划快照。</p></details></div>${active ? `<div class="rp-message" role="status">${e(this.label(active))}，更新完成后会覆盖当前报告。</div>` : ""}<div class="rp-reader" data-report-frame></div></div><div class="rp-reading-actions"><button class="rp-secondary" type="button" data-rp="regenerate" ${active || this.generating ? "disabled" : ""}>${this.icon("refresh")}重新生成</button></div>`
        : `<div class="rp-toolbar"><div class="segmented" role="group" aria-label="报告类型">${["daily", "weekly"].map((k) => `<button type="button" data-rp="kind" data-kind="${k}" aria-pressed="${this.kind === k}">${k === "daily" ? "日报" : "周报"}</button>`).join("")}</div><div class="rp-date-actions"><label class="rp-date-label">回顾${this.kind === "daily" ? "日期" : "所在周"}<input type="date" data-report-date value="${e(this.date)}" max="${this.today()}" min="2020-01-01" aria-label="报告日期"></label><button class="rp-secondary" type="button" data-rp="filter" aria-pressed="${this.filter}">${this.filter ? "查看全部" : "筛选日期"}</button><button class="primary-btn" type="button" data-rp="generate" ${this.generating ? "disabled" : ""}>${this.icon("bolt")}生成${this.kind === "daily" ? "日报" : "周报"}</button></div></div><div class="rp-auto-note">${this.icon("calendar")}<span>${this.schedules.map((s) => `${s.kind === "daily" ? "日报" : "周报"}${s.enabled ? ` ${s.kind === "weekly" ? ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][s.weekday] : "每天"} ${e(s.local_time)}` : "已关闭"}`).join(" · ")}${this.schedules.length ? ` · ${e(this.schedules[0].timezone)}` : "正在读取生成计划"}</span></div>${this.loadingDetail ? '<div class="rp-empty" role="status">正在打开报告…</div>' : this.status === "loading" && !this.items.length ? '<div class="rp-empty" role="status">正在读取报告…</div>' : this.status === "error" ? '<div class="rp-empty"><h2>暂时无法读取报告</h2><button class="rp-secondary" type="button" data-rp="refresh">重新读取</button></div>' : this.items.length ? `<div class="rp-archive">${this.items.map((r) => `<article class="rp-archive-card"><div class="rp-section-head"><span class="rp-tag">${r.kind === "daily" ? "日报" : "周报"} · ${e(this.range(r))}</span><span class="rp-state ${["running", "queued", "retrying"].includes(r.state) ? "pending" : ""}">${e(this.label(r))}</span></div><h2>${e(this.archiveTitle(r))}</h2><p>${e(this.archiveSummary(r))}</p>${["failed", "insufficient_data"].includes(r.state) && r.error_code ? `<small class="rp-caption">${e(this.error(r.error_code))}</small>` : ""}<div class="rp-card-bottom"><small class="rp-caption">${r.generated_at ? e(this.stamp(r.generated_at, r.timezone)) : "后台任务 · 离开页面后继续"}${r.coverage?.some((s) => ["partial", "unavailable", "not_integrated"].includes(s.status)) ? " · 数据有缺项" : ""}</small>${r.generated_at ? `<button class="text-link" type="button" data-rp="read" data-id="${r.id}">阅读报告 ${this.icon("arrow")}</button>` : ["failed", "insufficient_data"].includes(r.state) ? `<button class="text-link" type="button" data-rp="retry" data-kind="${r.kind}" data-date="${r.period_start}">重新生成 ${this.icon("refresh")}</button>` : ""}</div></article>`).join("")}</div>${this.cursor ? '<button class="rp-secondary rp-more" type="button" data-rp="more">加载更多</button>' : ""}` : `<div class="rp-empty"><h2>${this.filter ? "这个日期还没有报告" : "给记录留一点思考的时间。"}</h2><p>日报回看昨天，周报串起一周的变化。<br>可以先生成一份，也可以等待下一次自动回顾。</p><span class="rp-caption">内容由 AI 根据已有资料撰写，缺少的记录会在报告中说明。</span></div>`}`
    }</section>`;
  }
  mount() {
    const root = document.querySelector("[data-report-frame]");
    if (!root || !this.bundle) return;
    const frame = document.createElement("iframe");
    frame.title = "健康报告正文";
    frame.setAttribute("sandbox", "allow-scripts");
    frame.setAttribute("referrerpolicy", "no-referrer");
    frame.dataset.healthReportFrame = "";
    frame.onload = () =>
      frame.contentWindow.postMessage(
        {
          type: "health-report-theme",
          channel: this.bundle.channel,
          theme: document.documentElement.dataset.theme,
        },
        "*",
      );
    if (typeof HealthShare !== "undefined") HealthShare.registerFrame(frame, this.bundle.document);
    frame.srcdoc = this.bundle.document;
    root.replaceChildren(frame);
  }
}
window.HealthReports = HealthReports;
